def add(tags, codes, territory, rationale, sources="F_CIA73 F_ILO69", confidence="medium", status="historical_mapping", preserve=""):
    ideas = [CODES[c] for c in codes.split()]
    for tag in tags.split():
        if tag not in COUNTRIES:
            raise ValueError(f"Unknown tag {tag}")
        if tag in ROWS:
            raise ValueError(f"Duplicate {tag}")
        c = COUNTRIES[tag]
        ROWS[tag] = {
            "tag": tag, "name": c["name"], "ideas": ideas,
            "opinions": {i: 50 for i in ideas},
            "opinion_policy": "Preserve effective explicitly authored 1970 opinion values where present, including transitive initializer values. The listed 50 is MD's neutral initializer fallback, not an historical approval estimate.",
            "confidence": confidence, "status": status,
            "territory_1970": territory.format(name=c["name"]),
            "rationale": rationale.format(name=c["name"]),
            "source_ids": sources.split(),
            "preserve_authored_if_present": [CODES[c] for c in preserve.split()],
            "localisation_notes": [],
        }

def override(tag, codes=None, rationale=None, sources=None, confidence=None, status=None, territory=None, preserve=None):
    row = ROWS[tag]
    if codes is not None:
        row["ideas"] = [CODES[c] for c in codes.split()]
        row["opinions"] = {i: 50 for i in row["ideas"]}
    for name, value in (("rationale",rationale),("confidence",confidence),("status",status),("territory_1970",territory)):
        if value is not None: row[name] = value
    if sources: row["source_ids"] = sources.split()
    if preserve is not None: row["preserve_authored_if_present"] = [CODES[c] for c in preserve.split()]

