def attach_localisation_notes():
    locfile = ROOT.parents[1] / "localisation/english/MD_internal_factions_l_english.yml"
    existing = dict(re.findall(r'^\s*([A-Za-z0-9_]+):\s*"(.*)"\s*$', locfile.read_text(encoding="utf-8-sig"), re.M))
    for tag, row in ROWS.items():
        for idea in set(row["ideas"] + row["preserve_authored_if_present"]):
            key = f"{tag}_{idea}"
            if key in LABELS:
                label, reason, refs = LABELS[key]
                row["localisation_notes"].append({"idea": idea, "key": key, "current_label": existing.get(key, "No tag-specific key"), "proposed_label": label, "reason": reason, "source_ids": refs.split(), "scope": "Only selected or effectively authored 1970 groups; preserve original native text outside the 1970 start-date route."})
        row["localisation_notes"].sort(key=lambda x: x["key"])

def main():
    missing = sorted(set(COUNTRIES) - set(ROWS))
    if missing:
        print("UNASSIGNED:", " ".join(missing))
        for t in missing: print(t, COUNTRIES[t]["name"])
        raise SystemExit(1)
    for tag, row in ROWS.items():
        if row["status"] == "pending_user_review":
            assert row["ideas"] == []
            continue
        assert len(row["ideas"]) == len(set(row["ideas"])) == 3, tag
        assert set(row["ideas"]) <= NATIVE, tag
        assert set(row["source_ids"]) <= SOURCES.keys(), tag
        assert not set(row["ideas"]) & {"oligarchs", "the_donju", "iranian_quds_force", "foreign_jihadis"}, tag
    attach_localisation_notes()
    result = {
        "project": "IMPERIA COLD WAR", "date": "1970.1.1", "schema": 1,
        "methodology": [
            "Native faction groups are a qualitative three-slot representation of dominant institutions or social constituencies, not measured historical shares or approval ratings.",
            "The inventory records all 397 histories. Real territorial later releases receive researched territorial profiles. Four fictional/technical tags remain unassigned pending user review. Future armed organizations are not assigned their future ideology, patrons or governing institutions.",
            "Three is the standard representative profile and native UI slot count, not a demonstrated runtime hard limit. Preserve historically supported authored extras and their effects/opinions where national content relies on them.",
            "High confidence indicates a well-attested institutional match. Medium indicates a native-category mapping from country/territorial structures. Low indicates a coarse territorial or small-state proxy; fictional tags are explicitly not applicable.",
            "Near-period 1973 background material is not proof of the January 1970 government. Known 1969 and 1970 regime boundaries are handled explicitly. Contemporary records provide detailed checks for major country exceptions.",
            "Use existing MD 50 neutral opinion only where no explicitly authored 1970 value exists. An opinion value is a balance choice, not measured public support.",
            "Native tag-specific display labels are separately audited; a valid generic idea may otherwise show an organization founded after 1970.",
        ],
        "native_constraints": {
            "providers": ["common/ideas/AA_law_internal_factions.txt", "common/scripted_effects/00_internal_faction_effects.txt", "common/idea_tags/00_idea.txt"],
            "ui_slots": 3, "runtime_hard_limit_proven": False,
            "forbidden_anachronistic_ids": ["oligarchs", "the_donju", "iranian_quds_force", "foreign_jihadis"],
            "opinion_fallback": 50,
            "warning": "Do not run national focus completion or swap events to install history; add native ideas and authored starting opinion variables directly inside the guarded 1970 snapshot after its existing initialization effects.",
        },
        "sources": SOURCES,
        "countries": [ROWS[t] for t in sorted(ROWS)],
    }
    (ROOT / "factions.json").write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print("countries", len(ROWS), "sources", len(SOURCES), "profiles", len({tuple(x['ideas']) for x in ROWS.values()}))
    print("confidence", dict(Counter(x["confidence"] for x in ROWS.values())))
    print("status", dict(Counter(x["status"] for x in ROWS.values())))

if __name__ == "__main__": main()
